const item = $input.item.json;
const headers = item.headers || {};
const query = item.query || {};
const body = item.body || {};

// Server-side authentication check
const configuredSecret = $env.DASHBOARD_SECRET || '';
const clientSecret = headers['x-dashboard-secret'] || headers['authorization']?.replace(/^Bearer\s+/i, '').trim() || query.secret || body.secret || '';

// Whitelisted API actions
const allowedActions = [
  'SERVE_HTML',
  'GET_APPOINTMENTS',
  'CREATE_APPOINTMENT',
  'UPDATE_STATUS',
  'RESCHEDULE_APPOINTMENT',
  'CANCEL_APPOINTMENT',
  'SET_DOCTOR_LEAVE'
];

let action = 'SERVE_HTML';
if (body.action) {
  action = body.action;
} else if (query.action) {
  action = query.action;
}

let error = null;

if (!allowedActions.includes(action)) {
  action = 'INVALID_ACTION';
  error = 'Invalid action specified';
} else if (configuredSecret && clientSecret !== configuredSecret && action !== 'SERVE_HTML') {
  action = 'UNAUTHORIZED';
  error = 'Unauthorized: invalid or missing dashboard secret';
}

return [{
  json: {
    action: action,
    payload: body,
    query: query,
    error: error,
    received_at: new Date().toISOString()
  }
}];

