  <script>
    let allAppointments = [];
    let currentFilter = 'today';
    let currentPage = 1;
    const pageSize = 50;
    const apiUrl = window.location.pathname;

    function escapeHtml(str) {
      if (!str) return '';
      return String(str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#039;');
    }

    async function loadAppointments() {
      try {
        const res = await fetch(apiUrl, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ action: 'GET_APPOINTMENTS', page: currentPage, page_size: pageSize })
        });
        const result = await res.json();
        allAppointments = result.data?.appointments || result.appointments || [];
        applyFilters();
      } catch (err) {
        console.error('Failed to load appointments', err);
      }
    }

    function setFilter(f) {
      currentFilter = f;
      document.querySelectorAll('.btn-group button').forEach(b => b.classList.remove('active'));
      document.getElementById('filter-' + f).classList.add('active');
      applyFilters();
    }

    function applyFilters() {
      const search = document.getElementById('search-box').value.toLowerCase();
      const doctor = document.getElementById('doctor-filter').value;
      const now = new Date();

      let filtered = allAppointments.filter(a => {
        const aStart = new Date(a.start_time);
        const aLocalDate = new Intl.DateTimeFormat('en-CA', { timeZone: a.timezone || 'Asia/Kolkata' }).format(aStart);
        const todayLocalDate = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Kolkata' }).format(now);

        if (currentFilter === 'today' && aLocalDate !== todayLocalDate) return false;
        if (currentFilter === 'upcoming' && aStart <= now) return false; // Bug #22: start_time > NOW()
        if (doctor && a.doctor_id !== doctor) return false;
        if (search) {
          const matchName = (a.customer_name || '').toLowerCase().includes(search);
          const matchPhone = (a.phone || '').includes(search);
          if (!matchName && !matchPhone) return false;
        }
        return true;
      });

      // Stats
      const todayList = allAppointments.filter(a => new Intl.DateTimeFormat('en-CA', { timeZone: a.timezone || 'Asia/Kolkata' }).format(new Date(a.start_time)) === new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Kolkata' }).format(now));
      document.getElementById('stat-today').innerText = todayList.length;
      document.getElementById('stat-confirmed').innerText = todayList.filter(a => a.status === 'CONFIRMED').length;
      document.getElementById('stat-arrived').innerText = todayList.filter(a => a.status === 'ARRIVED').length;
      document.getElementById('stat-completed').innerText = todayList.filter(a => a.status === 'COMPLETED').length;

      renderTable(filtered);
    }

    function renderTable(list) {
      const tbody = document.getElementById('appointment-tbody');
      if (list.length === 0) {
        tbody.innerHTML = '<tr><td colspan="8" class="text-center py-4 text-muted">No appointments found for this filter.</td></tr>';
        return;
      }

      tbody.innerHTML = list.map(a => {
        const dt = new Date(a.start_time);
        const formattedDate = dt.toLocaleDateString('en-US', { timeZone: a.timezone || 'Asia/Kolkata', month: 'short', day: 'numeric', year: 'numeric' });
        const formattedTime = dt.toLocaleTimeString('en-US', { timeZone: a.timezone || 'Asia/Kolkata', hour: '2-digit', minute: '2-digit' });

        return `
          <tr>
            <td><span class="text-muted fw-bold">#\${escapeHtml(a.appointment_id)}</span></td>
            <td class="fw-semibold">\${escapeHtml(a.customer_name)}</td>
            <td><a href="https://wa.me/\${escapeHtml(a.phone)}" target="_blank" class="text-decoration-none"><i class="fa-brands fa-whatsapp text-success me-1"></i>\${escapeHtml(a.phone)}</a></td>
            <td><span class="badge bg-light text-dark border">\${escapeHtml(a.doctor_name || a.doctor_id)}</span></td>
            <td>\${escapeHtml(a.service)}</td>
            <td><strong>\${escapeHtml(formattedDate)}</strong> <span class="text-muted">\${escapeHtml(formattedTime)}</span></td>
            <td><span class="badge badge-status status-\${escapeHtml(a.status)}">\${escapeHtml(a.status)}</span></td>
            <td class="text-end">
              <div class="dropdown d-inline-block">
                <button class="btn btn-sm btn-light border dropdown-toggle" data-bs-toggle="dropdown">Actions</button>
                <ul class="dropdown-menu dropdown-menu-end">
                  <li><a class="dropdown-item text-primary" href="#" onclick="updateStatus(\${a.appointment_id}, 'ARRIVED')"><i class="fa-solid fa-door-open me-2"></i>Mark Arrived</a></li>
                  <li><a class="dropdown-item text-success" href="#" onclick="updateStatus(\${a.appointment_id}, 'COMPLETED')"><i class="fa-solid fa-check-double me-2"></i>Mark Completed</a></li>
                  <li><a class="dropdown-item text-secondary" href="#" onclick="updateStatus(\${a.appointment_id}, 'NO_SHOW')"><i class="fa-solid fa-user-slash me-2"></i>Mark No-Show</a></li>
                  <li><hr class="dropdown-divider"></li>
                  <li><a class="dropdown-item text-warning" href="#" onclick="openReschedModal(\${a.appointment_id}, '\${escapeHtml(a.customer_name)}')"><i class="fa-solid fa-calendar-days me-2"></i>Reschedule</a></li>
                  <li><a class="dropdown-item text-danger" href="#" onclick="cancelAppt(\${a.appointment_id})"><i class="fa-solid fa-trash me-2"></i>Cancel</a></li>
                </ul>
              </div>
            </td>
          </tr>
        `;
      }).join('');
    }

    async function updateStatus(id, newStatus) {
      if (!confirm('Update appointment #' + id + ' status to ' + newStatus + '?')) return;
      await fetch(apiUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'UPDATE_STATUS', appointment_id: id, status: newStatus })
      });
      loadAppointments();
    }

    async function cancelAppt(id) {
      if (!confirm('Cancel appointment #' + id + '?')) return;
      await fetch(apiUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'CANCEL_APPOINTMENT', appointment_id: id })
      });
      loadAppointments();
    }

    function openNewModal() {
      document.getElementById('m-date').value = new Date().toISOString().split('T')[0];
      document.getElementById('m-time').value = '10:00';
      new bootstrap.Modal(document.getElementById('newApptModal')).show();
    }

    async function submitNewAppointment() {
      const name = document.getElementById('m-name').value;
      const phone = document.getElementById('m-phone').value;
      const doctor = document.getElementById('m-doctor').value;
      const service = document.getElementById('m-service').value;
      const date = document.getElementById('m-date').value;
      const time = document.getElementById('m-time').value;

      if (!name || !phone || !date || !time) return alert('Please fill all fields');

      const res = await fetch(apiUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'CREATE_APPOINTMENT', customer_name: name, phone: phone, doctor_id: doctor, service: service, date: date, time: time })
      });
      const data = await res.json();
      if (!data.success) {
        alert('Booking failed: ' + (data.error?.message || 'Conflict detected'));
      } else {
        bootstrap.Modal.getInstance(document.getElementById('newApptModal')).hide();
        loadAppointments();
      }
    }

    function openReschedModal(id, name) {
      document.getElementById('r-id').value = id;
      document.getElementById('r-patient').innerText = name;
      document.getElementById('r-date').value = new Date().toISOString().split('T')[0];
      document.getElementById('r-time').value = '11:00';
      new bootstrap.Modal(document.getElementById('reschedModal')).show();
    }

    async function submitReschedule() {
      const id = document.getElementById('r-id').value;
      const date = document.getElementById('r-date').value;
      const time = document.getElementById('r-time').value;

      const res = await fetch(apiUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'RESCHEDULE_APPOINTMENT', appointment_id: id, date: date, time: time })
      });
      const data = await res.json();
      if (!data.success) {
        alert('Reschedule failed: ' + (data.error?.message || 'Slot occupied'));
      } else {
        bootstrap.Modal.getInstance(document.getElementById('reschedModal')).hide();
        loadAppointments();
      }
    }

    function openLeaveModal() {
      new bootstrap.Modal(document.getElementById('leaveModal')).show();
    }

    async function submitDoctorLeave() {
      const doctor = document.getElementById('l-doctor').value;
      const start = document.getElementById('l-start').value;
      const end = document.getElementById('l-end').value;
      const reason = document.getElementById('l-reason').value;

      const res = await fetch(apiUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'SET_DOCTOR_LEAVE', doctor_id: doctor, start_time: start, end_time: end, reason: reason })
      });
      const data = await res.json();
      if (data.data?.affected_appointments?.length > 0) {
        alert('Leave recorded. Notice: ' + data.data.affected_appointments.length + ' existing booking(s) fall in this window and need rescheduling.');
      } else {
        alert('Doctor unavailability recorded.');
      }
      bootstrap.Modal.getInstance(document.getElementById('leaveModal')).hide();
    }

    loadAppointments();
    setInterval(loadAppointments, 30000);
  </script>
</body>
</html>`;

return [{ json: { html: html } }];

