  const map = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 };
  return map[dayStr];
}

const prev = $('Prep_Manual_Create').first().json;
const docData = $input.first()?.json;

if (!docData || !docData.doctor_id) {
  throw new Error(`Doctor '${prev.doctor_id}' not found or inactive.`);
}

const tz = docData.timezone || 'Asia/Kolkata';
const durationMinutes = docData.slot_duration_minutes || 30;

const startUtc = getUtcFromLocal(prev.date, prev.time, tz);
const endUtc = new Date(startUtc.getTime() + durationMinutes * 60000);

// Check unavailabilities
const unavailabilities = Array.isArray(docData.unavailabilities) ? docData.unavailabilities : (typeof docData.unavailabilities === 'string' ? JSON.parse(docData.unavailabilities) : []);
for (const u of unavailabilities) {
  const uStart = new Date(u.start_time);
  const uEnd = new Date(u.end_time);
  if (startUtc < uEnd && endUtc > uStart) {
    throw new Error(`Doctor is unavailable at this time: ${u.reason || 'On Leave'}`);
  }
}

// Check existing confirmed appointments
const activeAppts = Array.isArray(docData.active_appointments) ? docData.active_appointments : (typeof docData.active_appointments === 'string' ? JSON.parse(docData.active_appointments) : []);
for (const a of activeAppts) {
  const aStart = new Date(a.start_time);
  const aEnd = new Date(a.end_time);
  if (startUtc < aEnd && endUtc > aStart) {
    throw new Error(`Time slot overlaps with existing appointment #${a.appointment_id} for ${a.customer_name}`);
  }
}

return [{
  json: {
    ...prev,
    doctor_name: docData.doctor_name,
    calendar_id: docData.calendar_id,
    timezone: tz,
    slot_duration_minutes: durationMinutes,
    start_time_iso: startUtc.toISOString(),
    end_time_iso: endUtc.toISOString()
  }
}];

